/**
 * generate-bundle — the MCP server's runtime data, frozen at build time.
 *
 * WHY
 *
 * Roadmap item 7: the packed MCP tarball must run its tools from a temp dir
 * outside the repo. Every tool that read a checkout file at runtime
 * (`get_tokens`, `get_dtcg`, `list_themes`, `list_blocks`/`get_block`)
 * returned an "unavailable" error outside a clone — the server ran, but its
 * data did not travel with it. This generator reads the live sources and
 * emits ONE typed module (`src/bundled-data.ts`, tracked + freshness-gated)
 * that `tools.ts` imports instead of reading files. No checkout file is read
 * at runtime for bundled data; a packed tarball serves it from dist.
 *
 * WHAT IS (AND IS NOT) BUNDLED
 *
 * Bundled: base tokens, the four theme presets + catalog, the DTCG
 * document, the block rows (metadata only — file bytes stay out; `kern add`
 * vendors those through the CLI). Deliberately NOT bundled: component
 * SOURCES (the 473KB COMPONENT_SOURCES precedent — verbatim source in a
 * generated module collides with the formatter and ships bytes nobody
 * asked for; `get_component` names the missing source explicitly instead).
 *
 * FRESHNESS
 *
 * The output is a registered `check:generated` artifact: editing a source
 * without regenerating fails the gate. Inside the workspace the tools serve
 * frozen-at-build data — the same contract `manifest.ts` already holds.
 */
import { readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { formatText } from "../../../scripts/lib/format-generated.mjs";

const HERE = dirname(fileURLToPath(import.meta.url));
const ROOT = join(HERE, "..", "..", "..");
const SRC = join(ROOT, "packages", "mcp", "src");

function readJson(rel) {
  try {
    return JSON.parse(readFileSync(join(ROOT, rel), "utf8"));
  } catch (err) {
    console.error(
      `generate-bundle FAILED — cannot read ${rel}: ${err.message}`,
    );
    process.exit(1);
  }
}

function readText(rel) {
  try {
    return readFileSync(join(ROOT, rel), "utf8");
  } catch (err) {
    console.error(
      `generate-bundle FAILED — cannot read ${rel}: ${err.message}`,
    );
    process.exit(1);
  }
}

// --- tokens: base + the four presets `get_tokens` accepts -----------------
const tokensBase = readJson("packages/kern-tokens/src/tokens.json");
const THEME_IDS = ["material-3", "sharp", "brand", "compact"];
const tokenThemes = {};
for (const id of THEME_IDS) {
  tokenThemes[id] = readJson(`packages/kern-m3/src/themes/${id}.json`);
}
const themesCatalog = readJson("packages/kern-m3/src/themes/index.json");
const dtcg = readJson("packages/kern-tokens/src/dtcg.json");

// --- blocks: the same rows `list_blocks` parsed at runtime ----------------
// One parse of the site block manifest (mirrors
// `packages/kern-cli/scripts/generate-blocks.mjs`, which carries file bytes
// the MCP server never serves — this payload carries metadata only). A row
// the manifest does not parse is refused here, not listed as installable.
const blockSrc = readText("apps/site/src/blocks/manifest.ts");
const bundledBlocks = [];
for (const chunk of blockSrc.split(/^\s*\{/m).slice(1)) {
  const name = chunk.match(/name:\s*"([^"]+)"/)?.[1];
  const file = chunk.match(/file:\s*"([^"]+)"/)?.[1];
  if (!name || !file) continue;
  const strList = (key) => {
    const body =
      chunk.match(new RegExp(`${key}:\\s*\\[([^\\]]*)\\]`, "s"))?.[1] ?? "";
    return [...body.matchAll(/"([^"]+)"/g)].map((m) => m[1]);
  };
  bundledBlocks.push({
    name,
    title: chunk.match(/title:\s*"([^"]+)"/)?.[1] ?? name,
    category: chunk.match(/category:\s*"([^"]+)"/)?.[1] ?? "Settings",
    description: chunk.match(/description:\s*"([^"]+)"/)?.[1] ?? "",
    files: [file, ...strList("files")],
    components: strList("registryDependencies"),
  });
}
if (bundledBlocks.length === 0) {
  console.error("generate-bundle FAILED — parsed 0 block rows.");
  process.exit(1);
}

const raw = `// GENERATED by packages/mcp/scripts/generate-bundle.mjs — do not hand-edit.
//
// The MCP server's runtime data, frozen at build time (roadmap item 7):
// base tokens, theme presets + catalog, the DTCG document, block metadata.
// tools.ts imports this module instead of reading checkout files, so the
// packed tarball serves data from dist with no repo to read. Regenerate with
// \`bun run generate:mcp-bundle\`; check:generated proves it is fresh.
export const BUNDLED_TOKENS_BASE: Record<string, unknown> = ${JSON.stringify(tokensBase)};

export const BUNDLED_TOKEN_THEMES: Record<string, Record<string, unknown>> = ${JSON.stringify(tokenThemes)};

export const BUNDLED_THEMES_CATALOG: unknown = ${JSON.stringify(themesCatalog)};

export const BUNDLED_DTCG: unknown = ${JSON.stringify(dtcg)};

export type BundledBlock = {
  name: string;
  title: string;
  category: string;
  description: string;
  files: string[];
  components: string[];
};

export const BUNDLED_BLOCKS: BundledBlock[] = ${JSON.stringify(bundledBlocks)};
`;

// Format-before-write (F-02 rule): the payload embeds JSON syntax that biome
// reformats, so an unformatted write would leave the file lint-dirty.
writeFileSync(
  join(SRC, "bundled-data.ts"),
  formatText({
    root: ROOT,
    text: raw,
    stdinFilePath: "bundled-data.ts",
    label: "generate-bundle: bundled-data.ts",
  }),
);

console.log(
  `generate-bundle: tokens base + ${THEME_IDS.length} presets + catalog + DTCG + ${bundledBlocks.length} blocks -> packages/mcp/src/bundled-data.ts`,
);
